package com.familyguard.parent;
import android.app.Activity;import android.os.Bundle;import android.graphics.Typeface;import android.widget.*;
import com.google.firebase.FirebaseApp;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.firestore.*;import java.security.SecureRandom;import java.util.*;
public class MainActivity extends Activity{
 LinearLayout root,requests;TextView status,codeView;FirebaseAuth auth;FirebaseFirestore db;ListenerRegistration listener;
 public void onCreate(Bundle b){super.onCreate(b);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,40,32,24);root.setBackgroundColor(0xFFF5F7FB);
 TextView title=new TextView(this);title.setText("FamilyGuard Parent");title.setTextSize(27);title.setTypeface(null,Typeface.BOLD);TextView intro=new TextView(this);intro.setText("Pair a Child device and review permission requests.");
 Button gen=new Button(this);gen.setText("Generate pairing code");gen.setOnClickListener(v->generateCode());codeView=new TextView(this);codeView.setText("No active code");codeView.setTextSize(22);status=new TextView(this);status.setText("Connecting to Firebase...");
 TextView h=new TextView(this);h.setText("Pending permission requests");h.setTextSize(20);requests=new LinearLayout(this);requests.setOrientation(1);
 root.addView(title);root.addView(intro);root.addView(gen);root.addView(codeView);root.addView(status);root.addView(h);root.addView(requests);setContentView(root);
 try{FirebaseApp.initializeApp(this);auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();auth.signInAnonymously().addOnSuccessListener(x->{status.setText("Parent connected. Generate a code to pair Child.");watch();}).addOnFailureListener(e->status.setText("Sign-in failed: "+e.getMessage()));}catch(Exception e){status.setText("Firebase setup error: "+e.getMessage());}}
 void generateCode(){if(auth.getUid()==null)return;String chars="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";SecureRandom r=new SecureRandom();StringBuilder s=new StringBuilder();for(int i=0;i<8;i++)s.append(chars.charAt(r.nextInt(chars.length())));String code=s.toString();Map<String,Object>d=new HashMap<>();d.put("parentUid",auth.getUid());d.put("createdAt",FieldValue.serverTimestamp());d.put("expiresAt",new Date(System.currentTimeMillis()+600000));d.put("consumedBy","");db.collection("pairCodes").document(code).set(d).addOnSuccessListener(x->{codeView.setText("PAIRING CODE\n"+code+"\nExpires in 10 minutes");status.setText("Enter this code on the Child phone.");}).addOnFailureListener(e->status.setText("Code error: "+e.getMessage()));}
 void watch(){if(listener!=null)listener.remove();listener=db.collection("approvalRequests").whereEqualTo("parentUid",auth.getUid()).whereEqualTo("status","pending").addSnapshotListener((snap,e)->{if(e!=null){status.setText("Sync error: "+e.getMessage());return;}requests.removeAllViews();if(snap==null||snap.isEmpty()){requests.addView(new TextView(this){{setText("No pending requests.");}});return;}for(DocumentSnapshot d:snap){TextView label=new TextView(this);label.setText((d.getString("childLabel")==null?"Child":d.getString("childLabel"))+" requests "+d.getString("permission"));LinearLayout row=new LinearLayout(this);Button yes=new Button(this),no=new Button(this);yes.setText("Approve");no.setText("Deny");yes.setOnClickListener(v->resolve(d.getId(),"approved"));no.setOnClickListener(v->resolve(d.getId(),"denied"));row.addView(yes,new LinearLayout.LayoutParams(0,-2,1));row.addView(no,new LinearLayout.LayoutParams(0,-2,1));requests.addView(label);requests.addView(row);}});}
 void resolve(String id,String value){db.collection("approvalRequests").document(id).update("status",value,"resolvedAt",FieldValue.serverTimestamp()).addOnFailureListener(e->status.setText("Update failed: "+e.getMessage()));}
 protected void onDestroy(){if(listener!=null)listener.remove();super.onDestroy();}
}